/* Boston Celtics DNA — garden night green, parquet floor, champion gold */
.theme-boston-celtics {
  --bg: oklch(0.232 0.038 168.6);
  --surface: oklch(0.279 0.047 167.5);
  --surface-2: oklch(0.325 0.055 166.6);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.768 0.039 166.2);
  --accent: oklch(0.506 0.142 149.2);
  --accent-fg: oklch(0.231 0.039 169.1);
  --accent-2: oklch(0.692 0.096 81.6);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-boston-celtics h1,
.theme-boston-celtics h2,
.theme-boston-celtics h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-boston-celtics { --font-ui: var(--font-display); }
.theme-boston-celtics h1, .theme-boston-celtics h2 { text-transform: uppercase; font-weight: 800; }
.theme-boston-celtics button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }

.theme-boston-celtics { background-image: repeating-linear-gradient(45deg, oklch(0.3 0.05 160 / 30%) 0 34px, transparent 34px 68px), repeating-linear-gradient(-45deg, oklch(0.3 0.05 160 / 30%) 0 34px, transparent 34px 68px); background-size: 100% 320px; background-repeat: no-repeat; }
.theme-boston-celtics h2::before { content: "☘ "; color: var(--accent); }
.theme-boston-celtics h1 { color: var(--accent); }

/* alt mode: auto-derived light variant */
.theme-boston-celtics.alt-mode {
  --bg: oklch(0.98 0.012 168.6);
  --surface: oklch(0.955 0.015 168.6);
  --surface-2: oklch(0.92 0.020 168.6);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
